import{_ as e,o as r,c as t,x as o}from"./chunks/framework.DzQQ_lrg.js";const i="/xi-kari-skill/handbook/images/recovery.svg",k=JSON.parse('{"title":"依靠支持恢复的功能，算不算真的恢复","description":"支持条件不抹去已恢复的功能；它限定了恢复声明的范围。","frontmatter":{"title":"依靠支持恢复的功能，算不算真的恢复","description":"支持条件不抹去已恢复的功能；它限定了恢复声明的范围。"},"headers":[],"relativePath":"concepts/recovery.md","filePath":"concepts/recovery.md"}'),l={name:"concepts/recovery.md"};function s(n,a,h,c,p,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="依靠支持恢复的功能-算不算真的恢复" tabindex="-1">依靠支持恢复的功能，算不算真的恢复 <a class="header-anchor" href="#依靠支持恢复的功能-算不算真的恢复" aria-label="Permalink to &quot;依靠支持恢复的功能，算不算真的恢复&quot;">​</a></h1><p>临时供电让服务重新可用，为什么既能算恢复，又不能说一切恢复如初？</p><p><strong>支持条件不抹去已恢复的功能；它限定了恢复声明的范围。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文用临时供电和持续支持说明恢复的范围。一项功能在支持下重新可用，已有结果就应该保留；不能仅因支持尚在，就把它说成没有恢复。与此同时，评价要写清依赖什么支持、在什么窗口内可用、实际覆盖了哪些人，不能把部分用户的恢复自动写成全部灾前用户均已恢复。</p><p>原文对学习作出相同的区分：支持下完成任务、撤除支持后的独立迁移、后续生活结果，是三个不同目标。若原目标本来就是协作或支持下完成，无支持失败不取消已有成功；若原目标是独立迁移，就需要相应比较。修复也不要求时间倒流，它可以改变组件、接口和载体，只要按事先明确的目标判断，并另行讨论目标、权限与责任。</p><figure class="concept-figure"><img src="'+i+'" alt="支持条件与恢复范围一起保留"><figcaption>支持下恢复、独立恢复和更广泛生活结果，具有不同的成立条件。</figcaption></figure><h2 id="真实案例-gitlab恢复了服务-为什么仍有数据损失" tabindex="-1">真实案例：GitLab恢复了服务，为什么仍有数据损失 <a class="header-anchor" href="#真实案例-gitlab恢复了服务-为什么仍有数据损失" aria-label="Permalink to &quot;真实案例：GitLab恢复了服务，为什么仍有数据损失&quot;">​</a></h2><p>2017年1月31日，GitLab.com主数据库的数据目录被误删。按GitLab自己的复盘，每天一次的逻辑备份并没有生成，团队改用约六小时前为测试环境手动做的一份LVM快照恢复数据库，再补回webhook。约18小时后服务重新可用，快照之后约六小时的数据库修改没有找回。两个结果同时成立：功能恢复了，不等于此前的数据都在；数据不完整，也不抹掉已经可用的功能。原文<a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-6">§6.6</a>的说法是：“对某项有限功能的确认，不要求其他全部结果同时恢复。”</p><p>到2月10日复盘发布时，恢复手段也还没有补齐：备库在重建，逻辑备份暂停（最近一份是三天前的），LVM快照改成了每小时一次，Azure磁盘快照还在研究。“服务能用”“恢复手段是否补齐”“下一次故障能否恢复”是三个问题，不能用一个“已恢复”概括；快照间隔也不等于恢复耗时。</p><p>这个案例说明的是恢复声明的<strong>范围</strong>——哪项功能、哪些数据、截至何时，不涉及撤去支持后的独立能力。分项记录见<a href="/xi-kari-skill/handbook/cases/gitlab-recovery.html">GitLab案例页</a>及其<a href="/xi-kari-skill/handbook/cases/gitlab-recovery.html#recovery-reserve">“哪些事还没有结案”</a>一节，事实出自<a href="https://about.gitlab.com/blog/postmortem-of-database-outage-of-january-31/" target="_blank" rel="noreferrer">GitLab的事故复盘</a>。</p><h2 id="判断恢复时-要分别核对什么" tabindex="-1">判断恢复时，要分别核对什么 <a class="header-anchor" href="#判断恢复时-要分别核对什么" aria-label="Permalink to &quot;判断恢复时，要分别核对什么&quot;">​</a></h2><p>原文<a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-6">§6.6</a>要求恢复判断同时说明四件事：恢复了什么、对谁、在什么支持条件下、截至何时。下面几组材料要分别取证，才不会把一项有限的恢复写成“一切恢复如初”。</p><ul><li><strong>功能与人群：</strong> 实际输出的数量、质量、持续性与可达性，各有什么记录？计算恢复比例时，灾前人口、当前人口、符合资格者和实际使用者不能默默互换。</li><li><strong>支持与接续：</strong> 依赖哪些临时场所、持续外援或辅助设备？支持能否持续，何时到期，替代承接是否已经运行？尚未经历的需求高峰、维护周期或季节性暴露，要明确写出来。</li><li><strong>内部余量与边界外负担：</strong> 内部的人员休整、备件、维护积压和资金接续怎样？边界之外有没有新增的照护、通勤、借款或替代服务负担？此后有没有中断和近失误？</li></ul><p>确认某一项有限功能已经恢复，不要求其余结果同时恢复；反过来，恢复声明也不能超出证据支持的对象、人群、功能或持续条件。</p><h2 id="自测-三个假设情景" tabindex="-1">自测：三个假设情景 <a class="header-anchor" href="#自测-三个假设情景" aria-label="Permalink to &quot;自测：三个假设情景&quot;">​</a></h2><p><strong>一、临时供电让一个服务点重新开放。记录显示，观察时段内实际到这个点的使用者能得到目标服务。能说恢复了吗？</strong></p><p>能，但要带着范围说：这个服务点、这些使用者、这个时段、临时供电条件下，目标功能已经恢复。仍靠临时供电，不是否认它的理由；这个结论也不能扩大成所有居民、全部功能或长期独立运行都已恢复。</p><p><strong>二、支持下的服务一直可用，但资助即将到期，接续安排还没有运行。要撤回此前的恢复判断吗？</strong></p><p>不用。依赖支持本身不是恢复失败。要另外核实的是支持能否持续、何时到期、替代承接是否已经运行；现在可用，推不出到期之后仍然可用。也不能为了验证恢复而撤走必要支持。</p><p><strong>三、后来服务再次停运。能直接说此前只是“假恢复”吗？</strong></p><p>不能。要分别比较旧损伤延续、储备未补回、支持中断、新冲击和测量口径改变。原文§6.6把“假恢复”限定为声明超出了证据支持的对象、人群、功能或持续条件，而且不由此推定欺骗；一次新的失败，不能抹去此前准确限定的成果。</p><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>临时支持下真实恢复的功能不是假的</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-6">§6.6 CM-LOAD 负荷、容量与恢复</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-10">§6.10 解体、对象转换与修复边界</a></li><li><a href="/xi-kari-skill/handbook/theory/part-06.html#section-6-3">§6.3 CM-LEARNING 反馈介导学习</a></li><li><a href="/xi-kari-skill/handbook/theory/appendix-d/d-31.html#section-d-31">附录D.31 风险、灾害、公共卫生、指挥与恢复</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>这是对原文恢复和学习边界的教学说明，不是具体灾后项目或临床个案的结论。功能恢复、长期生活结果、目标正当性和采用权限须分别判断。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./responsibility.html">实际做事的人，为什么不等于全部责任人</a></li><li><a href="./history.html">留下记录，与真正学会了什么</a></li></ul>',29)])])}const u=e(l,[["render",s]]);export{k as __pageData,u as default};
